# @faker.version next
def user(*args)
  user_hash = {}
  args = %w[username email] if args.empty?
  args.each { |arg| user_hash[:"#{arg}"] = send(arg) }
  user_hash
end

alias user_name username

private

def sanitize_email_local_part(local_part)
  char_range = [
    Array('0'..'9'),
    Array('A'..'Z'),
    Array('a'..'z'),
    "!#$%&'*+-/=?^_`{|}~.".chars
  ].flatten
